  {"year": "54–51 BC", "text": "Cicero writes On the Commonwealth"},
  {"year": "c. AD 57", "text": "Paul's Letter to the Romans"},
  {"year": "c. AD 305–311", "text": "Lactantius quotes Cicero's definition of true law"},
  {"year": "1270s", "text": "Thomas Aquinas on natural law"},
